)

class ConnectionManager:
    def __init__(self):
        self.active_connections: List[WebSocket] = []
        self.conversation_history: Dict[str, List] = {}

    async def connect(self, websocket: WebSocket):
        await websocket.accept()
        self.active_connections.append(websocket)

    def disconnect(self, websocket: WebSocket):
        self.active_connections.remove(websocket)

    async def send_personal_message(self, message: str, websocket: WebSocket):
        await websocket.send_text(message)

manager = ConnectionManager()

@app.websocket("/ws/{client_id}")
async def websocket_endpoint(websocket: WebSocket, client_id: str):
    await manager.connect(websocket)
    try:
        while True:
            data = await websocket.receive_text()
            message_data = json.loads(data)

            # Process AI request
            response = await process_ai_request(
                message_data['message'], 
                message_data.get('persona', 'assistant')
            )

            await manager.send_personal_message(
                json.dumps({
                    'type': 'ai_response',
                    'message': response,
                    'timestamp': str(datetime.now())
                }), 
                websocket
            )
    except WebSocketDisconnect:
        manager.disconnect(websocket)

async def process_ai_request(message: str, persona: str) -> str:
    try:
        response = ollama.chat(
            model='nous-hermes2:7b',
            messages=[
                {
                    'role': 'system',
                    'content': f'You are {persona}, an AI assistant with advanced capabilities.'
                },
                {
                    'role': 'user',
                    'content': message
                }
            ]
        )
        return response['message']['content']
    except Exception as e:
        return f"Error processing request: {str(e)}"

import React, { useRef, useEffect } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { OrbitControls, useGLTF } from '@react-three/drei';
import * as THREE from 'three';

interface Avatar3DProps {
  emotion: 'neutral' | 'happy' | 'thinking' | 'speaking';
  isAnimating: boolean;
}

const AvatarModel: React.FC<{ emotion: string; isAnimating: boolean }> = ({ emotion, isAnimating }) => {
  const meshRef = useRef<THREE.Mesh>(null);
  const { scene } = useGLTF('/models/cybria-avatar.glb');

  useFrame((state) => {
    if (meshRef.current && isAnimating) {
      meshRef.current.rotation.y = Math.sin(state.clock.elapsedTime) * 0.1;

      // Emotional expressions through subtle transformations
      switch (emotion) {
        case 'happy':
          meshRef.current.scale.setScalar(1 + Math.sin(state.clock.elapsedTime * 2) * 0.02);
          break;
        case 'thinking':
          meshRef.current.rotation.x = Math.sin(state.clock.elapsedTime * 0.5) * 0.05;
          break;
        case 'speaking':
          meshRef.current.position.y = Math.sin(state.clock.elapsedTime * 8) * 0.01;
          break;
        default:
          meshRef.current.scale.setScalar(1);
          meshRef.current.rotation.x = 0;
          meshRef.current.position.y = 0;
      }
    }
  });

  return (
    <primitive 
      ref={meshRef} 
      object={scene.clone()} 
      scale={1.5} 
      position={[0, -1, 0]} 
    />
  );
};

const Avatar3D: React.FC<Avatar3DProps> = ({ emotion, isAnimating }) => {
  return (
    <Canvas camera={{ position: [0, 0, 5], fov: 50 }}>
      <ambientLight intensity={0.4} />
      <directionalLight position={[10, 10, 5]} intensity={0.8} />
      <AvatarModel emotion={emotion} isAnimating={isAnimating} />
      <OrbitControls enableZoom={false} enablePan={false} />
    </Canvas>
  );
};

export default Avatar3D;

