import cv2
import numpy as np
from PIL import ImageGrab
import pyautogui
from typing import Tuple, Optional

class FishingDetector:
    def __init__(self):
        self.template_images = self.load_templates()
        self.fishing_active = False
        self.detection_threshold = 0.8

    def load_templates(self) -> dict:
        """Load template images for pattern matching"""
        templates = {}
        template_paths = {
            'fishing_rod': 'templates/fishing_rod.png',
            'fish_bite': 'templates/fish_bite.png',
            'water_ripple': 'templates/water_ripple.png'
        }

        for name, path in template_paths.items():
            try:
                templates[name] = cv2.imread(path, cv2.IMREAD_GRAYSCALE)
            except Exception as e:
                print(f"Failed to load template {name}: {e}")

        return templates

    def capture_screen_region(self, region: Tuple[int, int, int, int]) -> np.ndarray:
        """Capture specific screen region for analysis"""
        screenshot = ImageGrab.grab(bbox=region)
        screen_array = np.array(screenshot)
        return cv2.cvtColor(screen_array, cv2.COLOR_RGB2GRAY)

    def detect_fishing_opportunity(self, screen_region: np.ndarray) -> bool:
        """Detect if fishing opportunity is available"""
        if 'fishing_rod' not in self.template_images:
            return False

        result = cv2.matchTemplate(
            screen_region, 
            self.template_images['fishing_rod'], 
            cv2.TM_CCOEFF_NORMED
        )

        min_val, max_val, min_loc, max_loc = cv2.minMaxLoc(result)
        return max_val >= self.detection_threshold

    def detect_fish_bite(self, screen_region: np.ndarray) -> bool:
        """Detect fish bite indicators"""
        if 'fish_bite' not in self.template_images:
            return False

        result = cv2.matchTemplate(
            screen_region, 
            self.template_images['fish_bite'], 
            cv2.TM_CCOEFF_NORMED
        )

        min_val, max_val, min_loc, max_loc = cv2.minMaxLoc(result)
        return max_val >= self.detection_threshold

    def start_fishing_sequence(self) -> bool:
        """Execute fishing automation sequence"""
        try:
            # Cast fishing line
            pyautogui.click(button='right')
            time.sleep(0.5)

            # Wait for fish bite detection
            max_wait_time = 30  # seconds
            start_time = time.time()

            while time.time() - start_time < max_wait_time:
                screen = self.capture_screen_region((100, 100, 800, 600))

                if self.detect_fish_bite(screen):
                    # Fish detected, reel in
                    pyautogui.click(button='right')
                    return True

                time.sleep(0.1)

            return False

        except Exception as e:
            print(f"Fishing sequence error: {e}")
            return False

