import 'package:camera/camera.dart';
import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

class CameraService {
  static CameraService? _instance;
  static CameraService get instance => _instance ??= CameraService._();

  CameraService._();

  List<CameraDescription> _cameras = [];
  CameraController? _controller;
  bool _isInitialized = false;

  List<CameraDescription> get cameras => _cameras;
  CameraController? get controller => _controller;
  bool get isInitialized => _isInitialized;

  Future<void> initializeCameras() async {
    try {
      _cameras = await availableCameras();
      if (_cameras.isNotEmpty) {
        await _initializeController(_cameras.first);
      }
    } on CameraException catch (e) {
      debugPrint('Camera initialization error: ${e.code} - ${e.description}');
      rethrow;
    }
  }

  Future<void> _initializeController(CameraDescription camera) async {
    _controller = CameraController(
      camera,
      ResolutionPreset.high,
      enableAudio: false,
      imageFormatGroup: ImageFormatGroup.jpeg,
    );

    try {
      await _controller!.initialize();
      _isInitialized = true;
    } on CameraException catch (e) {
      debugPrint('Controller initialization error: ${e.code} - ${e.description}');
      _isInitialized = false;
      rethrow;
    }
  }

  Future<void> switchCamera(CameraDescription camera) async {
    if (_controller != null) {
      await _controller!.dispose();
    }
    await _initializeController(camera);
  }

  Future<CameraTestResult> runCameraTest() async {
    if (!_isInitialized || _controller == null) {
      return CameraTestResult(
        success: false,
        error: 'Camera not initialized',
        timestamp: DateTime.now(),
      );
    }

    try {
      // Test camera preview
      final previewSize = _controller!.value.previewSize;
      if (previewSize == null) {
        throw CameraException('PREVIEW_ERROR', 'Unable to get preview size');
      }

      // Test image capture
      final XFile image = await _controller!.takePicture();
      final imageSize = await image.length();

      // Test flash modes if available
      final flashModes = await _getAvailableFlashModes();

      return CameraTestResult(
        success: true,
        previewSize: previewSize,
        imageSize: imageSize,
        flashModes: flashModes,
        timestamp: DateTime.now(),
      );

    } on CameraException catch (e) {
      return CameraTestResult(
        success: false,
        error: '${e.code}: ${e.description}',
        timestamp: DateTime.now(),
      );
    }
  }

  Future<List<FlashMode>> _getAvailableFlashModes() async {
    final List<FlashMode> modes = [];

    for (final mode in FlashMode.values) {
      try {
        await _controller!.setFlashMode(mode);
        modes.add(mode);
      } catch (e) {
        // Flash mode not supported
      }
    }

    return modes;
  }

  void dispose() {
    _controller?.dispose();
    _controller = null;
    _isInitialized = false;
  }
}

class CameraTestResult {
  final bool success;
  final String? error;
  final Size? previewSize;
  final int? imageSize;
  final List<FlashMode>? flashModes;
  final DateTime timestamp;

  CameraTestResult({
    required this.success,
    this.error,
    this.previewSize,
    this.imageSize,
    this.flashModes,
    required this.timestamp,
  });
}
